function applyTheme(){document.body.classList.toggle('dark',theme==='dark');$('#theme').textContent=theme==='dark'?'☀':'☾';$('#theme').setAttribute('aria-label',t(theme==='dark'?'light':'dark'))}
const languageNames={uz:'O‘zbekcha',ru:'Русский',en:'English'};
function syncLanguagePicker(){
 $('#language-label').textContent=languageNames[lang];
 document.querySelectorAll('[data-language]').forEach(option=>option.setAttribute('aria-selected',String(option.dataset.language===lang)));
}
function setupLanguagePicker(){
 const picker=$('#language-picker'),trigger=$('#language'),menu=$('#language-options'),options=[...menu.querySelectorAll('[data-language]')];
 const close=(focus=false)=>{picker.classList.remove('open');trigger.setAttribute('aria-expanded','false');menu.setAttribute('aria-hidden','true');menu.inert=true;if(focus)trigger.focus()};
 const open=()=>{picker.classList.add('open');trigger.setAttribute('aria-expanded','true');menu.setAttribute('aria-hidden','false');menu.inert=false;requestAnimationFrame(()=>{if(picker.classList.contains('open'))(options.find(option=>option.dataset.language===lang)||options[0]).focus()})};
 trigger.onclick=()=>picker.classList.contains('open')?close():open();
 options.forEach(option=>option.onclick=()=>{if(videoUploading){close(true);toast(t('videoWait'));return}if(dialog.open)closeDialog();lang=option.dataset.language;storage.set('language',lang);translate();close(true)});
 picker.addEventListener('keydown',event=>{
  if(event.key==='Escape'){event.preventDefault();close(true);return}
  if(event.key==='Tab')return;
  if(event.target===trigger&&['ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();open();return}
  if(!picker.classList.contains('open'))return;
  const index=options.indexOf(document.activeElement);let next=index;
  if(event.key==='ArrowDown')next=(index+1)%options.length;else if(event.key==='ArrowUp')next=(index-1+options.length)%options.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=options.length-1;else return;
  event.preventDefault();options[next].focus();
 });
 document.addEventListener('pointerdown',event=>{if(!picker.contains(event.target))close()});
 picker.addEventListener('focusout',event=>{if(!picker.contains(event.relatedTarget))close()});
}

function translate(){clearTimeout(toastTimer);$('#toast').classList.remove('show');$('#toast').textContent='';document.documentElement.lang=lang;document.title=t('langTitle');document.querySelectorAll('[data-t]').forEach(e=>{if(e.dataset.t==='heroTitle')e.innerHTML=t(e.dataset.t);else e.textContent=t(e.dataset.t)});syncLanguagePicker();$('#close-dialog').setAttribute('aria-label',t('close'));$('#search').placeholder=t('searchPlaceholder');$('#search').setAttribute('aria-label',t('searchPlaceholder'));$('#sort').innerHTML=[['default','sortDefault'],['az','sortAZ']].map(([v,k])=>`<option value="${v}">${t(k)}</option>`).join('');$('#sort').value=sort;applyTheme();updateAccount();render()}
async function api(path,options={}){
 if(location.protocol==='file:')throw new Error('LOCAL');
 let r;try{r=await fetch('/api/'+path,{...options,credentials:'same-origin',cache:'no-store',headers:{...(!(options.body instanceof FormData)?{'Content-Type':'application/json'}:{}),...options.headers}})}catch(err){if(err.name==='AbortError')throw err;throw new Error('NETWORK_ERROR')}
 let data;try{data=await r.json()}catch{throw new Error(r.status===429?'RATE_LIMITED':r.status===403?'ACCESS_BLOCKED':r.status>=500?'SERVER_ERROR':'INVALID_SERVER_RESPONSE')}
 if(!r.ok)throw new Error(data.error||(r.status===429?'RATE_LIMITED':r.status>=500?'SERVER_ERROR':'INVALID_SERVER_RESPONSE'));
 return data;
}
