let selectedPhoto=null,photoObjectUrl=null,photoSequence=0,photoWorking=false;
function clearPhoto(){photoSequence++;selectedPhoto=null;photoWorking=false;if(photoObjectUrl)URL.revokeObjectURL(photoObjectUrl);photoObjectUrl=null}
function photoField(){return `<div class="photo-field"><span class="field-label">${t('photo')}</span><label class="photo-drop" id="photo-drop"><input type="file" id="photo-file" name="photo" accept="image/jpeg,image/png,image/webp"><span class="photo-upload-icon">▧</span><strong>${t('choosePhoto')}</strong><span>${t('photoHint')}</span></label><div id="photo-preview" class="photo-preview" hidden><img id="photo-preview-image" alt="${esc(t('photoPreview'))}"><button class="photo-remove" type="button" id="remove-photo" aria-label="${esc(t('removePhoto'))}">×</button><span class="photo-ready">✓ ${t('photoReady')}</span></div><p class="map-hint" id="photo-status" role="status" aria-live="polite"></p></div>`}
function setupPhotoField(){clearPhoto();const input=$('#photo-file');if(!input)return;$('#remove-photo').onclick=()=>{clearPhoto();input.value='';$('#photo-preview').hidden=true;$('#photo-drop').hidden=false;$('#photo-status').textContent=''};input.addEventListener('change',async()=>{const file=input.files?.[0];if(!file)return;clearPhoto();const sequence=photoSequence;const status=$('#photo-status'),preview=$('#photo-preview'),drop=$('#photo-drop');if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){input.value='';status.textContent=t('photoInvalid');return}photoWorking=true;status.textContent=t('photoProcessing');try{let image,release;if(typeof createImageBitmap==='function'){image=await createImageBitmap(file);release=()=>image.close()}else{const url=URL.createObjectURL(file);image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=url});release=()=>URL.revokeObjectURL(url)}if(!image.width||!image.height){release();throw new Error('INVALID_IMAGE')}const scale=Math.min(1,1600/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);release();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.86));if(!blob||blob.size>5*1024*1024)throw new Error('INVALID_IMAGE');if(sequence!==photoSequence)return;selectedPhoto=blob;photoObjectUrl=URL.createObjectURL(blob);$('#photo-preview-image').src=photoObjectUrl;preview.hidden=false;drop.hidden=true;status.textContent=t('photoReady')}catch{if(sequence===photoSequence){input.value='';status.textContent=t('photoInvalid')}}finally{if(sequence===photoSequence)photoWorking=false}})}
function openPhotoEdit(id){if(!user){openAuth();return}show(`<h2>${t('editPhoto')}</h2><form id="photo-edit-form" class="form" data-ad-id="${esc(id)}">${photoField()}<p class="form-error" id="photo-edit-error" hidden role="alert"></p><button type="submit" class="primary">${t('savePhoto')}</button></form>`);setupPhotoField()}
document.addEventListener('click',e=>{const button=e.target.closest('[data-edit-photo]');if(button)openPhotoEdit(button.dataset.editPhoto)});
document.addEventListener('submit',async e=>{if(e.target.id!=='photo-edit-form')return;e.preventDefault();const form=e.target,button=form.querySelector('button[type="submit"]'),error=$('#photo-edit-error');if(photoWorking){toast(t('photoProcessing'));return}if(!selectedPhoto){error.textContent=t('choosePhoto');error.hidden=false;return}button.disabled=true;error.hidden=true;const payload=new FormData();payload.set('photo',selectedPhoto,'photo.jpg');try{const id=form.dataset.adId;await api('ads/'+id+'/image',{method:'POST',body:payload});closeDialog();await loadAds();openAd(id);toast(t('photoSaved'))}catch(err){error.textContent=t(['INVALID_PHOTO','UPLOAD_TOO_LARGE'].includes(err.message)?'photoInvalid':'photoError');error.hidden=false;button.disabled=false}});

let selectedVideo=null,videoPreviewUrl=null,videoUploading=false,videoController=null,videoUploadState=null;
const VIDEO_MAX=1_000_000_000;
function clearVideo(){if(videoUploading)return;if(videoPreviewUrl)URL.revokeObjectURL(videoPreviewUrl);videoPreviewUrl=null;selectedVideo=null;if(videoUploadState){const state=videoUploadState;videoUploadState=null;api('ads/'+state.adId+'/video/uploads/'+state.id,{method:'DELETE'}).catch(()=>{})}}
function videoField(){return `<div class="video-field"><span class="field-label">${t('video')}</span><label class="photo-drop video-drop" id="video-drop"><input type="file" id="video-file" accept="video/mp4,video/webm,.mp4,.webm"><span class="photo-upload-icon">▷</span><strong>${t('chooseVideo')}</strong><span>${t('videoHint')}</span></label><div id="video-preview" class="video-preview" hidden><video controls playsinline preload="metadata" id="local-video-preview"></video><div class="video-file-row"><span id="video-filename"></span><button type="button" class="text-button" id="remove-video">${t('removeVideo')}</button></div></div><p class="map-hint" id="video-status" role="status" aria-live="polite"></p><div class="video-upload-progress" id="video-progress" hidden><progress max="100" value="0"></progress><span role="status" aria-live="polite"></span><button type="button" class="text-button" id="cancel-video-upload">${t('cancelVideo')}</button></div></div>`}
function setupVideoField(){clearVideo();const input=$('#video-file');if(!input)return;input.onchange=()=>{const file=input.files?.[0];if(!file)return;clearVideo();let type=file.type||(/\.webm$/i.test(file.name)?'video/webm':/\.mp4$/i.test(file.name)?'video/mp4':'');if(!['video/mp4','video/webm'].includes(type)||file.size<12||file.size>VIDEO_MAX){input.value='';$('#video-status').textContent=t('videoInvalid');return}selectedVideo={file,type};videoPreviewUrl=URL.createObjectURL(file);$('#local-video-preview').src=videoPreviewUrl;$('#video-filename').textContent=file.name+' · '+(file.size/1_000_000).toFixed(1)+' MB';$('#video-preview').hidden=false;$('#video-drop').hidden=true;$('#video-status').textContent=t('videoReady')};$('#remove-video').onclick=()=>{clearVideo();input.value='';$('#local-video-preview').removeAttribute('src');$('#video-preview').hidden=true;$('#video-drop').hidden=false;$('#video-status').textContent=''};$('#cancel-video-upload').onclick=()=>videoController?.abort()}
async function uploadVideo(adId,selection){
 videoUploading=true;videoController=new AbortController();const signal=videoController.signal,box=$('#video-progress'),meter=box.querySelector('progress'),status=box.querySelector('[role="status"]');box.hidden=false;$('#cancel-video-upload').hidden=false;$('#video-file').disabled=true;$('#remove-video').disabled=true;const setProgress=n=>{const percent=Math.floor(n/selection.file.size*100);meter.value=percent;status.textContent=t('videoUploading')+' '+percent+'% · '+(n/1_000_000).toFixed(1)+' / '+(selection.file.size/1_000_000).toFixed(1)+' MB'};setProgress(0);
 const retry=async fn=>{for(let attempt=0;;attempt++){try{return await fn()}catch(err){if(signal.aborted||attempt===2||['INVALID_VIDEO','INVALID_PART_SIZE','AUTH_REQUIRED','FORBIDDEN','VIDEO_TOO_LARGE','UPLOAD_EXPIRED'].includes(err.message))throw err;await new Promise(resolve=>setTimeout(resolve,800*(attempt+1)))}}};
 try{
  let state=videoUploadState;if(state&&state.adId===adId){try{const remote=await api('ads/'+adId+'/video/uploads/'+state.id,{signal});state.received=remote.received;if(remote.status==='completed'){videoUploadState=null;return}}catch(err){if(signal.aborted)throw err;state=null}}
  if(!state){const created=await api('ads/'+adId+'/video/uploads',{method:'POST',signal,body:JSON.stringify({size:selection.file.size,type:selection.type})});state=videoUploadState={...created,adId}}
  const base='ads/'+adId+'/video/uploads/'+state.id;setProgress(state.received);while(state.received<selection.file.size){const start=state.received,part=Math.floor(start/state.chunk_size)+1,chunk=selection.file.slice(start,Math.min(start+state.chunk_size,selection.file.size));const result=await retry(()=>api(base+'/part?number='+part,{method:'PUT',body:chunk,headers:{'Content-Type':'application/octet-stream'},signal}));state.received=result.received;setProgress(state.received)}
  status.textContent=t('videoFinishing');await retry(()=>api(base+'/complete',{method:'POST',signal}));videoUploadState=null;meter.value=100;status.textContent=t('videoSaved');
 }catch(err){if(signal.aborted&&videoUploadState){const state=videoUploadState;videoUploadState=null;await api('ads/'+adId+'/video/uploads/'+state.id,{method:'DELETE'}).catch(()=>{})}throw err}finally{videoUploading=false;videoController=null;$('#video-file')?.removeAttribute('disabled');$('#remove-video')?.removeAttribute('disabled');$('#cancel-video-upload')?.setAttribute('hidden','')}
}
function openVideoEdit(id){if(!user){openAuth();return}show(`<h2>${t('editVideo')}</h2><form id="video-edit-form" class="form" data-ad-id="${esc(id)}">${videoField()}<p class="form-error" id="video-edit-error" role="alert" hidden></p><button type="submit" class="primary">${t('saveVideo')}</button></form>`);setupVideoField()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-edit-video]');if(b)openVideoEdit(b.dataset.editVideo)});
document.addEventListener('submit',async e=>{if(e.target.id!=='video-edit-form')return;e.preventDefault();if(videoUploading)return;const form=e.target,error=$('#video-edit-error'),button=form.querySelector('[type="submit"]');if(!selectedVideo){error.textContent=t('chooseVideo');error.hidden=false;return}error.hidden=true;button.disabled=true;try{await uploadVideo(form.dataset.adId,selectedVideo);const id=form.dataset.adId;closeDialog();await loadAds();openAd(id);toast(t('videoSaved'))}catch{error.textContent=t('videoError');error.hidden=false;button.disabled=false;$('#cancel-video-upload').hidden=false}});
window.addEventListener('beforeunload',e=>{if(videoUploading){e.preventDefault();e.returnValue=''}});
dialog.addEventListener('cancel',e=>{if(videoUploading){e.preventDefault();toast(t('videoWait'))}});

function updateAccount(){AdminPanel.sync();const button=$('#account-button');if(!button)return;button.textContent=user?user.name:t('signIn');button.title=user?t('myAccount'):t('signIn');button.setAttribute('aria-label',user?t('myAccount')+': '+user.name:t('signIn'))}
function openAuth(mode='login',next=false){authContinue=next;const register=mode==='register';show(`<h2>${t(register?'register':'signIn')}</h2><p>${t(register?'registerIntro':'authIntro')}</p><form id="auth-form" class="form" data-mode="${mode}">${register?`<label>${t('name')}<input name="name" minlength="2" maxlength="80" autocomplete="name" placeholder="${esc(t('nameExample'))}" required></label>`:''}<label>${t('email')}<input name="email" type="email" maxlength="200" autocomplete="email" placeholder="${esc(t('emailExample'))}" required></label><label>${t('password')}<input name="password" type="password" minlength="8" maxlength="128" autocomplete="${register?'new-password':'current-password'}" placeholder="${esc(t('passwordHint'))}" required></label><p class="form-error" id="auth-error" role="alert" hidden></p><button type="submit" class="primary">${t(register?'registerSubmit':'authSubmit')}</button></form><button class="text-button" data-auth-mode="${register?'login':'register'}">${t(register?'haveAccount':'needAccount')}</button>`)}
function openAccount(){if(!user){openAuth();return}show(`<h2>${t('myAccount')}</h2><p><strong>${esc(user.name)}</strong></p><p>${esc(user.email)}</p><div class="dialog-actions"><button class="primary" data-account-ads="1">${t('requests')}</button><button class="outline" data-view="messages">${t('messages')}</button>${user.is_admin?`<button class="outline" data-view="admin">${t('admin')}</button>`:''}<button class="outline" data-logout="1">${t('logout')}</button></div>`)}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='account-button')openAccount();if(b.dataset.authMode)openAuth(b.dataset.authMode,authContinue);if(b.dataset.accountAds){closeDialog();setView('requests')}if(b.dataset.logout){b.disabled=true;try{await api('auth/logout',{method:'POST'});user=null;updateAccount();closeDialog();await loadAds();toast(t('logoutDone'))}catch{toast(t('authGeneric'));b.disabled=false}}});
document.addEventListener('submit',async e=>{if(e.target.id!=='auth-form')return;e.preventDefault();const form=e.target,button=form.querySelector('button[type="submit"]'),error=$('#auth-error');button.disabled=true;button.textContent=t('authBusy');error.hidden=true;try{const r=await api('auth/'+form.dataset.mode,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});if(!r.user?.id)throw new Error('INVALID_SERVER_RESPONSE');const session=await api('auth/me');if(session.user?.id!==r.user.id)throw new Error('SESSION_NOT_SAVED');user=session.user;const next=authContinue;closeDialog();updateAccount();await loadAds();toast(t('authSuccess'));if(next)openAdd();else AdMessaging.resume()}catch(err){const keys={INVALID_CREDENTIALS:'authInvalid',INVALID_AUTH_FIELDS:'authFields',EMAIL_EXISTS:'authExists',RATE_LIMITED:'authRate',NETWORK_ERROR:'authNetwork',INVALID_ORIGIN:'authOrigin',ACCESS_BLOCKED:'authBlocked',SERVER_ERROR:'authServer',DATABASE_UNAVAILABLE:'authServer',INVALID_SERVER_RESPONSE:'authResponse',SESSION_NOT_SAVED:'authSession'};error.textContent=t(keys[err.message]||'authGeneric');error.hidden=false;button.disabled=false;button.textContent=t(form.dataset.mode==='register'?'registerSubmit':'authSubmit')}});
async function init(){try{user=(await api('auth/me')).user}catch{user=null}updateAccount();await loadAds()}

document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){if(dialog.open){closeDialog();if(dialog.open)return}setView(b.dataset.view);return}if(b.dataset.category){category=b.dataset.category;if(view==='guides')view='offers';render();$('#content').scrollIntoView({behavior:'smooth'});return}if(b.dataset.save){saved=saved.includes(b.dataset.save)?saved.filter(x=>x!==b.dataset.save):[...saved,b.dataset.save];storage.set('ad-saved',saved);render();return}if(b.dataset.ad){openAd(b.dataset.ad);return}if(b.dataset.retry){loadAds();return}if(b.dataset.delete){if(!confirm(t('confirmRemove')))return;b.disabled=true;try{await api('ads/'+b.dataset.delete,{method:'DELETE',headers:{...(tokens[b.dataset.delete]?{'X-Delete-Token':tokens[b.dataset.delete]}:{})}});delete tokens[b.dataset.delete];storage.set('ad-tokens',tokens);closeDialog();await loadAds();toast(t('removed'))}catch{toast(t('deleteError'));b.disabled=false}return}if(b.dataset.action==='add')openAdd();if(b.dataset.action==='how')info('how');if(b.dataset.action==='privacy')info('privacy')});
document.addEventListener('submit',async e=>{if(e.target.id==='search-form'){e.preventDefault();query=$('#search').value.trim();render();return}if(e.target.id!=='ad-form')return;e.preventDefault();const form=e.target,f=new FormData(form),data=Object.fromEntries(f),error=$('#form-error'),button=$('#publish-button');data.phone=(data.phone||form.elements.phone.value).replace(/[\s()-]/g,'');if(!/^\+998\d{9}$/.test(data.phone)){error.textContent=t('phoneError');error.hidden=false;return}if(!form.elements.lat.value||!form.elements.lng.value){error.textContent=t('pickLocation');error.hidden=false;return}data.lat=Number(data.lat);data.lng=Number(data.lng);if(photoWorking){toast(t('photoProcessing'));return}button.disabled=true;button.textContent=t('publishing');error.hidden=true;let body;if(selectedPhoto){f.set('photo',selectedPhoto,'photo.jpg');body=f}else{delete data.photo;body=JSON.stringify(data)}try{let result;if(form.dataset.adId)result={ad:{id:form.dataset.adId}};else{result=await api('ads',{method:'POST',body});form.dataset.adId=result.ad.id}if(selectedVideo){form.querySelectorAll('input:not(#video-file),textarea,.category-trigger').forEach(el=>el.disabled=true);await uploadVideo(result.ad.id,selectedVideo)}closeDialog();view='offers';category='all';query='';$('#search').value='';await loadAds();$('#content').scrollIntoView({behavior:'smooth'});toast(t('published'))}catch(err){if(err.message==='AUTH_REQUIRED'){user=null;updateAccount();openAuth('login',true);return}error.textContent=t(form.dataset.adId?'videoError':err.message==='INVALID_PHONE'?'phoneError':err.message==='INVALID_LOCATION'?'pickLocation':'postError');error.hidden=false;button.disabled=false;button.textContent=t(form.dataset.adId?'retryVideo':'publish');$('#cancel-video-upload')?.removeAttribute('hidden')}});
setupLanguagePicker();$('#theme').onclick=()=>{theme=theme==='dark'?'light':'dark';storage.set('theme',theme);applyTheme()};$('#sort').onchange=e=>{sort=e.target.value;render()};$('#search').oninput=e=>{query=e.target.value.trim();render()};$('#explore').onclick=()=>setView('offers');$('#close-dialog').onclick=closeDialog;dialog.addEventListener('close',()=>{AdMessaging.stop();pauseMedia();clearVideo();clearPhoto();mapInstance?.destroy();mapInstance=null});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});$('.brand').onclick=e=>{e.preventDefault();setView('offers',false);window.scrollTo({top:0,behavior:'smooth'})};translate();init();
